const toast=(msg,ms=3200)=>{const el=$('#toast');if(!el)return;el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),ms)};
function getPath(obj,path){return String(path).split('.').reduce((a,k)=>a?.[k],obj)}
function setPath(obj,path,value){const keys=String(path).split('.');let cur=obj;keys.slice(0,-1).forEach(k=>cur=cur[k]??={});cur[keys.at(-1)]=value}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1200)}
function dataUrlToBytes(dataUrl){const b64=String(dataUrl).split(',')[1]||'';const raw=atob(b64),out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out}
function bytesToDataUrl(bytes,type='application/octet-stream'){let s='';const a=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);for(let i=0;i<a.length;i+=0x8000)s+=String.fromCharCode(...a.subarray(i,i+0x8000));return `data:${type};base64,${btoa(s)}`}
function fileToDataUrl(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
function concatBytes(parts){const total=parts.reduce((s,p)=>s+p.length,0),out=new Uint8Array(total);let o=0;for(const p of parts){out.set(p,o);o+=p.length}return out}
async function sha256Bytes(bytes){const h=await crypto.subtle.digest('SHA-256',bytes instanceof ArrayBuffer?bytes:bytes.buffer.slice(bytes.byteOffset,bytes.byteOffset+bytes.byteLength));return [...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join('')}

let db=null;
const state={current:null,processPage:1,managementPage:1,filters:{process:{q:'',district:'',place:'',agro:false},management:{q:'',district:'',place:'',agro:false}},deferredInstall:null,dirty:false,swRegistration:null};

/* ---------- Almacenamiento aislado ---------- */
function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const d=req.result;if(!d.objectStoreNames.contains(STORE_CASES))d.createObjectStore(STORE_CASES,{keyPath:'id'})};req.onsuccess=()=>{db=req.result;resolve(db)};req.onerror=()=>reject(req.error)})}
function txStore(mode='readonly'){return db.transaction(STORE_CASES,mode).objectStore(STORE_CASES)}
function idbAll(){return new Promise((resolve,reject)=>{const r=txStore().getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)})}
function idbGet(id){return new Promise((resolve,reject)=>{const r=txStore().get(id);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)})}
function idbPut(c){return new Promise((resolve,reject)=>{const r=txStore('readwrite').put(c);r.onsuccess=()=>resolve(c);r.onerror=()=>reject(r.error)})}
function idbDelete(id){return new Promise((resolve,reject)=>{const r=txStore('readwrite').delete(id);r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}

function blankPolygon(index){return{id:uid(),name:`Polígono ${index}`,points:[],factor:'',drawing:true}}
function blankConstruction(index){return{id:uid(),name:`Construcción ${index}`,typology:'',quantityUnit:'m²',manualMeasure:'',levels:'1',age:'',condition:'',walls:'',roofCover:'',roofStructure:'',ceilings:'',floors:'',electrical:'',details:'',uiMd:false,uiOpen:true,activePolygonId:'',polygons:[]}}
function blankCase(){const stamp=nowIso();return {id:uid(),stage:'active',createdAt:stamp,updatedAt:stamp,general:{folio:'',tramite:'',finca:'',plano:'',propietario:'',identificacion:'',areaRegistro:'',origenDato:'Dato registral',tipoTramite:'Fiscalización',usoObservado:'',fechaDeclaracion:today(),distrito:'',lugar:'',direccionFinca:'',derecho:'',provincia:'HEREDIA',canton:'SARAPIQUÍ',celular:'',telefono:'',correo:'',representante:'',representanteCedula:'',representanteCelular:'',fax:'',otroTel:'',zona:'',observaciones:''},location:{east:'',north:'',crs:CRS,takenAt:today()},terrain:{topography:'',slope:'',streetLevel:'',streetLevelDifference:'',accessType:'',surface:'',services1Code:'',services2Code:'',waterAffected:'',waterNotes:'',agroDeclared:'No',agroActivity:'',agroArea:'',agroNotes:'',notes:''},constructions:[],photos:[],fiscalization:{landValueMatches:'',constructionMatches:'',constructionMeasureMatches:'',agroActivityMatches:'',agroAreaMatches:'',notes:''},report:{responsibleName:'',responsiblePosition:'Encargado(a) del Departamento de Catastro y Valoración',responsibleDateTime:new Date().toISOString().slice(0,16),rectificationOfficeNo:''},uiState:{md:{}}}}
function normalizeCase(c){const base=blankCase();const out={...base,...c,general:{...base.general,...c?.general},location:{...base.location,...c?.location},terrain:{...base.terrain,...c?.terrain},fiscalization:{...base.fiscalization,...c?.fiscalization},report:{...base.report,...c?.report},uiState:{md:{...(c?.uiState?.md||{})}},constructions:Array.isArray(c?.constructions)?c.constructions:[],photos:Array.isArray(c?.photos)?c.photos:[]};out.constructions=out.constructions.map((x,i)=>({...blankConstruction(i+1),...x,id:x.id||uid(),name:x.name||`Construcción ${i+1}`,quantityUnit:x.quantityUnit||inferQuantityUnit(x.typology),uiMd:!!x.uiMd,uiOpen:x.uiOpen!==false,polygons:(Array.isArray(x.polygons)?x.polygons:[]).map((p,j)=>({...blankPolygon(j+1),...p,id:p.id||uid(),name:p.name||`Polígono ${j+1}`,points:(p.points||[]).map(q=>({x:num(q.x),y:num(q.y)})),drawing:!!p.drawing}))}));return out}

async function saveCase(silent=false){if(!state.current)return;state.current.updatedAt=nowIso();await idbPut(structuredClone(state.current));state.dirty=false;broadcastChange(state.current.id);if(!silent)toast('Expediente guardado.');await renderLists()}
async function selectCase(id,view='record'){const c=await idbGet(id);if(!c)return;state.current=normalizeCase(c);state.dirty=false;renderCurrent();showView(view)}
async function createCase(){if(state.current&&state.dirty)await saveCase(true);state.current=blankCase();await idbPut(state.current);renderCurrent();await renderLists();showView('record');toast('Nuevo trámite creado.')}
async function removeCase(id){if(!confirm('¿Eliminar este expediente de esta V01? Esta acción no afecta otras instalaciones.'))return;await idbDelete(id);if(state.current?.id===id)state.current=null;renderCurrent();await renderLists();toast('Expediente eliminado de V01.')}
function markDirty(){state.dirty=true}

let bc=null;try{bc=new BroadcastChannel(BC_NAME);bc.onmessage=()=>renderLists()}catch(_){ }
if(!sessionStorage.getItem(SESSION_KEY))sessionStorage.setItem(SESSION_KEY,uid());
function broadcastChange(id){try{bc?.postMessage({id,at:Date.now()});localStorage.setItem(EVENT_KEY,JSON.stringify({id,at:Date.now()}))}catch(_){} }
window.addEventListener('storage',e=>{if(e.key===EVENT_KEY)renderLists()});

