function targetServiceWorkerScope(){return new URL('./',location.href).href.split('#')[0].split('?')[0]}
function registrationScriptUrls(reg){return [reg?.active?.scriptURL,reg?.waiting?.scriptURL,reg?.installing?.scriptURL].filter(Boolean)}
function isOurServiceWorkerRegistration(reg){return !!reg&&registrationScriptUrls(reg).some(u=>String(u).includes('sw.js?app=fiscalizacion-v01-mejorada-20260822'))}
async function exactScopeRegistration(){const reg=await navigator.serviceWorker.getRegistration('./');return reg&&reg.scope===targetServiceWorkerScope()?reg:null}
async function registerServiceWorker(){if(!('serviceWorker'in navigator)||location.protocol==='file:')return null;try{const existing=await exactScopeRegistration();if(existing&&!isOurServiceWorkerRegistration(existing)){toast('Esta ruta ya pertenece a otra aplicación instalada. V01 no la reemplazará: publíquela en un repositorio o subruta nueva.',7000);return null}state.swRegistration=existing||await navigator.serviceWorker.register(SW_URL,{scope:'./',updateViaCache:'none'});return state.swRegistration}catch(e){console.error(e);toast('No se pudo registrar el servicio sin conexión.');return null}}
async function checkUpdate(){if(!('serviceWorker'in navigator))return toast('Servicio de actualización no disponible.');if(!state.swRegistration)state.swRegistration=await exactScopeRegistration();if(!state.swRegistration)return toast('Servicio de actualización de V01 no disponible.');if(!isOurServiceWorkerRegistration(state.swRegistration))return toast('La ruta pertenece a otra aplicación. V01 no la modificará.',6000);await state.swRegistration.update();if(state.swRegistration.waiting)state.swRegistration.waiting.postMessage('SKIP_WAITING');toast('V01 revisada. Si existe una actualización, se aplicará únicamente a esta instalación.')}

