document.addEventListener('click',e=>{const b=e.target.closest('[data-choice-path-value]');if(!b||!state.current)return;const p=b.dataset.choicePathValue,v=b.dataset.choiceValue;setPath(state.current,p,getPath(state.current,p)===v?'':v);markDirty();renderChoiceGroups(b.closest('.module-body')||document);afterFieldChange(p)});

