function mdValues(d){const vals=[];$$('[data-choice-path]',d).forEach(h=>{const v=getPath(state.current,h.dataset.choicePath);if(v)vals.push(v)});$$('[data-path]',d).forEach(el=>{const v=getPath(state.current,el.dataset.path);if(v&&v!=='No')vals.push(v)});return [...new Set(vals)].slice(0,12)}
function refreshMdOne(d){if(!state.current)return;const on=!!state.current.uiState.md[d.dataset.md],b=d.querySelector('.md-btn'),box=d.querySelector('.md-summary');if(b){b.setAttribute('aria-pressed',String(on));b.textContent=on?'MD (✓)':'MD ( )'}if(box){const vals=mdValues(d);box.innerHTML=vals.map(v=>`<span>${esc(v)}</span>`).join('');box.hidden=d.open||!on||!vals.length}}
