async function buildRectificationPreviewHtml(c){const no=await ensureRectificationOfficeNumber(c),rows=rectificationReasonRows(c);return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(no)}_TRAMITE_${esc(c.general.tramite||'')}</title><style>${previewCss}.page{padding:.15in .4in .25in}.recthead{height:1.2in}.recthead .head{height:1.12in}.goldline{height:4px;background:#d5aa21;margin:4px 0}.yellowbar{background:#d5aa21;color:white;text-align:center;font-weight:bold;padding:5px}.greenbar{background:#2d8739;color:white;text-align:center;font-weight:bold;padding:5px}.redbar{background:red;color:white;text-align:center;font-weight:bold;padding:5px}.smallp{font-size:8.5px;line-height:1.5}</style></head><body><section class="page"><div class="head recthead"><img src="escudo-sarapiqui.png"><div><h1>MUNICIPALIDAD DE SARAPIQUÍ</h1><p>DEPARTAMENTO DE CATASTRO Y VALORACIÓN</p><p>TELEFONO: 4000-6700 Ext.2029 / 2072 / 2038</p><h2>PRESENTACIÓN DE RECTIFICACIÓN DE<br>DECLARACIÓN DEL BIEN INMUEBLE</h2><small>Ley de impuestos sobre bienes inmuebles (ley 7509 y sus reformas)</small></div><div class="right"><small>Código: BI-001</small><small>Versión: 1.0</small><small>Fecha: Julio 2026</small><br><small>OFICIO NÚMERO</small><b>${esc(no)}</b><small>${ddmmyyyy()}</small></div></div><div class="goldline"></div><div class="yellowbar">CUADRO N.1: DATOS DEL PROPIETARIO</div><table class="table"><tr><th>NOMBRE</th><td>${esc(c.general.propietario||'')}</td><th>CEDULA</th><td>${esc(c.general.identificacion||'')}</td></tr><tr><th>DIRECCIÓN FISCAL:</th><td colspan="3">${esc(c.general.direccionFinca||'')}</td></tr><tr><th>PROVINCIA</th><td>${esc(c.general.provincia||'')}</td><th>CANTON</th><td>${esc(c.general.canton||'')}</td></tr><tr><th>DISTRITO</th><td>${esc(c.general.distrito||'')}</td><th>CEL.</th><td>${esc(c.general.celular||'')}</td></tr><tr><th>TEL.</th><td>${esc(c.general.telefono||'')}</td><th>CORREO</th><td>${esc(c.general.correo||'')}</td></tr><tr><th>REPRESENTANTE LEGAL:</th><td>${esc(c.general.representante||'')}</td><th>CEDULA</th><td>${esc(c.general.representanteCedula||'')}</td></tr></table><p class="smallp">Se encontró que la información de bienes inmuebles de estas propiedades descritas en el cuadro N.2 debe rectificarse, por ello se le invita a modificar la declaración, en atención al artículo 68 del reglamento de bienes inmuebles.</p><p class="smallp">Para ello se le concede un plazo máximo de diez días a partir de la entrega de esta notificación para actualizar la respectiva declaración de bienes inmuebles.</p><div class="greenbar">CUADRO N.2: DATOS DEL INMUEBLE</div><table class="table"><tr><th>CONSECUTIVO DBI</th><th>N° DE FINCA</th><th>DERECHO</th><th>N° DE PLANO</th><th>DISTRITO</th></tr><tr><td>${esc(c.general.tramite||'')}</td><td>${esc(c.general.finca||'')}</td><td>${esc(c.general.derecho||'')}</td><td>${esc(c.general.plano||'')}</td><td>${esc(c.general.distrito||'')}</td></tr><tr><th>DIRECCIÓN DE FINCA / FOLIO</th><td colspan="4">${esc(c.general.direccionFinca||casePlace(c)||'')}</td></tr></table><div class="redbar">OBJETO DE RECHAZO</div><table class="table"><tr><th>${esc(rows[0].label)}</th><td>${esc(rows[0].reason)}</td></tr><tr><th>${esc(rows[1].label)}</th><td>${esc(rows[1].reason)}</td></tr></table><div class="rect-note">NOTA: SE LE RECUERDA QUE DEBE DECLARAR LA TOTALIDAD DE LOS BIENES INMUEBLES INSCRITOS A SU NOMBRE. CON EL FIN DE AGILIZAR EL TRÁMITE, ES OBLIGATORIO DETALLAR LAS CARACTERÍSTICAS DE CADA FINCA.</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:15px"><div style="text-align:center;padding-top:50px;border-bottom:1px solid #333">FIRMA DEL PERITO VALUADOR</div><div></div></div><p class="smallp">NOTIFICADOR : ____________________________________ &nbsp;&nbsp;&nbsp; FIRMA : ____________________________________</p><p class="smallp">FIRMA DE QUIEN RECIBE, DUEÑO O REPRESENTANTE LEGAL: ________________________________________________</p></section></body></html>`}
async function refreshReportPreview(){if(!state.current)return;$('#reportPreviewFrame').srcdoc=await buildReportPreviewHtml(state.current)}
async function refreshRectificationPreview(){if(!state.current||decisionFor(state.current).result!=='OBJETAR')return;$('#rectificationPreviewFrame').srcdoc=await buildRectificationPreviewHtml(state.current)}
async function refreshOutputUI(){if(!state.current)return;await syncRectificationVisibility();await refreshReportPreview();if(decisionFor(state.current).result==='OBJETAR')await refreshRectificationPreview()}
$('#refreshReportPreviewBtn')?.addEventListener('click',refreshReportPreview);$('#refreshRectPreviewBtn')?.addEventListener('click',refreshRectificationPreview);
function printHtml(html,title){const w=window.open('','_blank');if(!w)return toast('El navegador bloqueó la ventana de impresión.');w.document.open();w.document.write(html.replace(/<title>.*?<\/title>/,`<title>${esc(title)}</title>`));w.document.close();w.addEventListener('load',()=>setTimeout(()=>w.print(),350),{once:true})}
$('#printReportBtn')?.addEventListener('click',async()=>{if(state.current)printHtml(await buildReportPreviewHtml(state.current),`Informe_${safeFile(state.current.general.tramite)}`)});
$('#printRectBtn')?.addEventListener('click',async()=>{if(state.current){const no=await ensureRectificationOfficeNumber(state.current);printHtml(await buildRectificationPreviewHtml(state.current),`${no}_TRAMITE_${safeFile(state.current.general.tramite)}`)}});

