function xmlBytes(doc){let s=new XMLSerializer().serializeToString(doc);if(!s.startsWith('<?xml'))s='<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'+s;return new TextEncoder().encode(s)}
function wTables(doc){return [...doc.getElementsByTagNameNS(W_NS,'tbl')]}
function wRows(tbl){return [...tbl.children].filter(n=>n.namespaceURI===W_NS&&n.localName==='tr')}
function wCells(row){return [...row.children].filter(n=>n.namespaceURI===W_NS&&n.localName==='tc')}
function wText(el){return [...el.getElementsByTagNameNS(W_NS,'t')].map(n=>n.textContent||'').join('')}
function setWText(el,value,templateRun=null){let nodes=[...el.getElementsByTagNameNS(W_NS,'t')];if(!nodes.length){const doc=el.ownerDocument,p=[...el.getElementsByTagNameNS(W_NS,'p')][0]||(()=>{const x=doc.createElementNS(W_NS,'w:p');el.appendChild(x);return x})(),r=doc.createElementNS(W_NS,'w:r'),sourcePr=templateRun?.getElementsByTagNameNS(W_NS,'rPr')?.[0];if(sourcePr)r.appendChild(sourcePr.cloneNode(true));const t=doc.createElementNS(W_NS,'w:t');r.appendChild(t);p.appendChild(r);nodes=[t]}nodes[0].textContent=String(value??'');if(/^\s|\s$/.test(String(value??'')))nodes[0].setAttributeNS('http://www.w3.org/XML/1998/namespace','xml:space','preserve');for(let i=1;i<nodes.length;i++)nodes[i].textContent=''}
function valueTemplateRun(tbl,targetRow,targetCell){const rows=wRows(tbl),scan=[];const row=rows[targetRow];if(row){const cells=wCells(row);for(let d=1;d<cells.length;d++){for(const ci of [targetCell-d,targetCell+d])if(ci>=0&&ci<cells.length&&ci%2===1)scan.push(cells[ci])}}for(const r of rows){const cells=wCells(r);for(let ci=1;ci<cells.length;ci+=2)scan.push(cells[ci])}for(const c of scan){const run=c.getElementsByTagNameNS(W_NS,'r')?.[0];if(run&&wText(c).trim())return run}return tbl.getElementsByTagNameNS(W_NS,'r')?.[0]||null}
