function setExactText(doc,old,value,occurrence=0){const nodes=[...doc.getElementsByTagNameNS(W_NS,'t')].filter(n=>(n.textContent||'')===old);if(nodes[occurrence])nodes[occurrence].textContent=String(value);return!!nodes[occurrence]}
