async function canvasDataUrl(width,height,drawer){const c=document.createElement('canvas');c.width=width;c.height=height;drawer(c,c.getContext('2d'));return c.toDataURL('image/png')}
async function constructionSketchDataUrl(c,width=1100,height=520){return canvasDataUrl(width,height,(canvas,ctx)=>{ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);if(!c||!c.polygons?.length){ctx.fillStyle='#62736b';ctx.font='bold 28px Arial';ctx.textAlign='center';ctx.fillText('SIN CROQUIS REGISTRADO',width/2,height/2);return}const clone={...c,polygons:c.polygons};drawConstructionCanvas(clone,canvas,ctx);ctx.fillStyle='#17251f';ctx.font='bold 18px Arial';ctx.textAlign='center';ctx.fillText(`Área total: ${fmt2(constructionMeasure(c))} ${c.quantityUnit} · Perímetro de control: ${fmt2(constructionPerimeter(c))} m`,width/2,height-18)})}
async function photoPngDataUrl(photo,width=1100,height=620){return new Promise(resolve=>{const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.fillStyle='#eef1ef';ctx.fillRect(0,0,width,height);if(!photo?.dataUrl){ctx.fillStyle='#465b50';ctx.font='bold 34px Arial';ctx.textAlign='center';ctx.fillText('SIN FOTOGRAFÍA REGISTRADA',width/2,height/2);return resolve(canvas.toDataURL('image/png'))}const img=new Image();img.onload=()=>{const scale=Math.min(width/img.width,height/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(width-w)/2,(height-h)/2,w,h);resolve(canvas.toDataURL('image/png'))};img.onerror=()=>resolve(canvas.toDataURL('image/png'));img.src=photo.dataUrl})}

